import sys

def count_file(filename):
    """Counts lines, words, and characters in a file."""
    try:
        with open(filename, 'r') as f:
            lines = 0
            words = 0
            chars = 0
            for line in f:
                lines += line.count('\n')
                words += len(line.split())
                chars += len(line)
            return lines, words, chars
    except FileNotFoundError:
        print(f"wc: {filename}: No such file or directory", file=sys.stderr)
        return None
    except Exception as e:
        print(f"wc: {filename}: {e}", file=sys.stderr)
        return None

def main():
    files = sys.argv[1:]
    if not files:
        return

    for filename in files:
        result = count_file(filename)
        if result:
            lines, words, chars = result
            # Using a format similar to wc: 7 spaces for each number
            print(f"{lines:>7} {words:>7} {chars:>7} {filename}")

if __name__ == "__main__":
    main()

